from pathlib import Path
import json,gzip,hashlib,sys
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt
root=Path.cwd();sys.path.insert(0,str(root/'scripts/reinforcement_learning/rsl_rl'))
from diagnose_motion_policy_symmetry import rotation_matrix as R
base=root/'learnings/policy_tuning/RobotLab-Isaac-BeyondMimic-Flat-LW-wheel-v0'
runs={'no_height':('2026-11-07_15-01-47','wheel-to-leg-fixed-start-20261108-001'),'height':('2026-11-06_11-39-51','wheel-to-leg-fixed-start-20261107-001'),'current':('2026-11-08_11-04-17','wheel-to-leg-position-height-20261109-001')}
out=base/runs['current'][0]/'evaluations'/runs['current'][1]/'derived';analysis=json.loads((out/'analysis.json').read_text())
ref=lambda p:{'path':str(p),'sha256':hashlib.sha256(p.read_bytes()).hexdigest()}
rms=lambda x:float(np.sqrt(np.mean(np.asarray(x)**2)))
def env(v):return {'min':float(min(v)),'max':float(max(v)),'mean':float(np.mean(v))}
stats={};inputs=[ref(out/'analysis.json')];curves={};reference=None
for version,(run,batch) in runs.items():
 stats[version]={}
 for case in ['nominal','randomized']:
  p=base/run/'evaluations'/batch/'raw'/f'fixed-start-{case}-a01/telemetry.json.gz'
  with gzip.open(p,'rt') as f:t=json.load(f)
  inputs.append(ref(p));md=t['motion_diagnostics'];npz=Path(md['motion_file']['path']);m=np.load(npz);bi=md['initial_runtime']['body_names'].index('base_link');rb=md['body_names'].index('base_link');refpos=m['body_pos_w'][:,bi];mt=np.arange(len(refpos))/50
  assert ref(npz)['sha256']==md['motion_file']['sha256']
  reference={'motion':ref(npz),'base_z_peak_m':float(refpos[55:86,2].max()),'base_COM_vz_peak_m_s':float(m['body_lin_vel_w'][55:86,bi,2].max()),'base_COM_vx_peak_m_s':float(m['body_lin_vel_w'][55:86,bi,0].max()),'takeoff_time_s':1.3,'landing_time_s':1.6}
  rows=[];allss=t['samples'];allps=t['physics_samples'];wi=[i for i,n in enumerate(t['joint_names']) if 'wheel' in n];names=t['joint_names'];lsh=names.index('left_shank_joint')
  for e in analysis['statistics'][version][case]['episodes']:
   if not e['complete_success']:continue
   ss=[s for s in allss if s['episode_id']==e['episode']];ps=[s for s in allps if s['episode_id']==e['episode']]
   frame=np.array([s['frame_index'] for s in ss]);time=frame/50+.02;pos=np.array([s['root_position_w'] for s in ss]);vel=np.array([R(s['root_quaternion_w'])@s['root_linear_velocity_b'] for s in ss])
   recorded_ref=np.array([s['reference_body_position_w'] for s in ss]).reshape(-1,len(md['body_names']),3)[:,rb]
   offsets=recorded_ref-refpos[frame];origin=offsets[0];assert np.max(np.abs(offsets-origin))<1e-5
   aligned=np.stack([np.interp(time,mt,refpos[:,j])+origin[j] for j in range(3)],axis=1);error=pos-aligned;valid=time<=mt[-1]+1e-9
   jump=(time>=1.1)&(time<=1.7);land=(time>=1.45)&(time<=1.9);pt=np.array([s['frame_index']/50+(s['substep']+1)*.005 for s in ps]);phase_t=np.array([s['frame_index']/50 for s in ps]);pv=np.array([s['joint_velocity'] for s in ps]);pa=np.array([s['joint_acceleration'] for s in ps]);late=phase_t>=1.85;posq=np.array([s['joint_position'] for s in ss]);a=e['air_start_s'];l=e['landing_s']
   signed_velocity=vel[jump,2];imax=np.where(jump)[0][np.argmax(signed_velocity)];minq=np.where((time>=1.1)&(time<=1.5))[0];imin=minq[np.argmin(posq[minq,lsh])]
   row={'episode':e['episode'],'aligned_3D_position_rmse_m':float(np.sqrt(np.mean(np.sum(error[valid]**2,axis=1)))),'aligned_xyz_rmse_m':[rms(error[valid,j]) for j in range(3)],'aligned_landing_z_rmse_m':rms(error[land,2]),'landing_x_error_m':float(np.interp(l,time,pos[:,0])-np.interp(l,mt,refpos[:,0])-origin[0]),'end_x_error_m':float(np.interp(mt[-1],time,pos[:,0])-refpos[-1,0]-origin[0]),'base_dx_takeoff_to_landing_m':float(np.interp(l,time,pos[:,0])-np.interp(a,time,pos[:,0])),'base_COM_vz_peak_m_s':float(vel[imax,2]),'base_COM_vz_peak_time_s':float(time[imax]),'base_COM_vz_at_air_interpolated_m_s':float(np.interp(a,time,vel[:,2])),'base_COM_vx_peak_jump_m_s':float(vel[jump,0].max()),'base_COM_vx_at_landing_interpolated_m_s':float(np.interp(l,time,vel[:,0])),'late_wheel_speed_rms_rad_s':rms(pv[late][:,wi]),'late_wheel_speed_peak_rad_s':float(np.abs(pv[late][:,wi]).max()),'late_wheel_acceleration_rms_rad_s2':rms(pa[late][:,wi]),'late_wheel_acceleration_peak_rad_s2':float(np.abs(pa[late][:,wi]).max()),'left_shank_min_q_time_s':float(time[imin]),'left_shank_min_q_rad':float(posq[imin,lsh])}
   rows.append(row);curves[version,case,e['episode']]={'time':time,'x':pos[:,0]-origin[0],'z':pos[:,2]-origin[2],'vz':vel[:,2],'vx':vel[:,0]}
  stats[version][case]={'episodes':rows,'envelopes':{k:env([row[k] for row in rows]) for k in rows[0] if k not in ['episode','aligned_xyz_rmse_m']},'aligned_xyz_rmse_mean_m':np.mean([row['aligned_xyz_rmse_m'] for row in rows],axis=0).tolist(),'landing_x_error_mean_abs_m':float(np.mean([abs(row['landing_x_error_m']) for row in rows]))}
fig,axs=plt.subplots(3,2,figsize=(12,10),sharex=True)
for col,case in enumerate(['nominal','randomized']):
 for version,color in [('no_height','tab:orange'),('height','tab:green'),('current','tab:blue')]:
  for e in range(5):
   c=curves[version,case,e];mask=(c['time']>=.9)&(c['time']<=2.0)
   for row,k in enumerate(['x','vx','vz']):axs[row,col].plot(c['time'][mask],c[k][mask],color=color,alpha=.7 if case=='nominal' else .35,label=version if e==0 else None)
 for row,(label,values) in enumerate([('Base link X (m)',refpos[:,0]),('Base COM Vx (m/s)',m['body_lin_vel_w'][:,bi,0]),('Base COM Vz (m/s)',m['body_lin_vel_w'][:,bi,2])]):
  mask=(mt>=.9)&(mt<=2.0);axs[row,col].plot(mt[mask],values[mask],'k--',label='reference');axs[row,col].set_ylabel(label);axs[row,col].grid(alpha=.25)
 axs[0,col].set_title(case);axs[0,col].legend(fontsize=8);axs[-1,col].set_xlabel('Physical motion time (s)')
fig.tight_layout();fig.savefig(out/'position-velocity-comparison.png',dpi=150);plt.close(fig)
result={'version':1,'source':CODE_SOURCE,'inputs':inputs,'reference':reference,'statistics':stats,'conventions':{'position':'Base link-origin world position minus original reference positions plus environment origin; no per-episode fitting or removal of reset position error. Reference linearly interpolated at physical control time frame/50+.02. Full-cycle RMSE excludes final sample beyond reference horizon3.38s.','velocity':'World base COM velocity rotated from telemetry; liftoff/landing values interpolated from20ms control samples; peaks are20ms sampled, not5ms exact.','landing':'Contact times from analysis.json; landing X error at each actual landing time; averages include five complete cycles only.','late_wheels':'Reference command phase>=1.85s, first50Hz frame1.86;5ms physics data, only complete cycles, left/right pooled RMS.','comparison':'Three8192-env server policies; no_height=Nov7 full-wheel/height0/std.30, height=Nov6 height2/no-wheel/std.30, current=Nov8 height2/late-wheel/std.15. Multiple reward changes; not a single-factor causal experiment.'}}
with (out/'position-velocity-analysis.json').open('x') as f:json.dump(result,f,indent=2,allow_nan=False)
print('POSITION_ANALYSIS_READY')
